-- MySQL schema + seed for the dialect-compat tests. MySQL doesn't support
-- "GENERATED BY DEFAULT AS IDENTITY" (SQL:2003 syntax) — use AUTO_INCREMENT
-- which is MySQL's equivalent. The application code (mapper queries) doesn't
-- care about the difference; this is purely a DDL convention split.
CREATE TABLE IF NOT EXISTS test_users (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    created_at TIMESTAMP    NOT NULL
);

